   183→  // Each degree drop reduces yield by 7% (conservative mid-range)
   184→  const yieldLoss = Math.abs(tempAnomaly) * 0.07;
   185→  return Math.max(0.05, 1.0 - yieldLoss);  // Minimum 5% yield (some crops survive)
   186→}
