   188→/**
   189→ * Calculate monthly starvation rate
   190→ * 
   191→ * Research (Robock & Toon 2012):
   192→ * - Peak starvation: Months 6-24 after war
   193→ * - 5% monthly mortality during peak
   194→ * - Gradual decline as crops partially recover
   195→ * 
   196→ * @param cropYield - Crop yield multiplier [0,1]
   197→ * @param monthsSinceWar - Months since nuclear war
   198→ * @returns Monthly starvation rate [0,1]
   199→ */
   200→function calculateStarvationRate(cropYield: number, monthsSinceWar: number): number {
   201→  // Food shortage severity (1 - crop yield)
   202→  const shortage = 1 - cropYield;
   203→  
   204→  // Starvation ramps up over first 6 months (takes time for food stocks to run out)
   205→  let rampMultiplier = 1.0;
   206→  if (monthsSinceWar < 6) {
   207→    rampMultiplier = monthsSinceWar / 6;  // Linear ramp: 0 → 1.0 over 6 months
   208→  }
   209→  
   210→  // Peak starvation: months 6-24
   211→  // After month 24, gradual decline as agriculture partially recovers
   212→  let recoveryMultiplier = 1.0;
   213→  if (monthsSinceWar > 24) {
   214→    // Exponential decay: 50% reduction every 24 months
   215→    recoveryMultiplier = Math.pow(0.5, (monthsSinceWar - 24) / 24);
   216→  }
   217→  
   218→  // Base starvation rate scales with shortage severity
   219→  // Research: 90% crop failure → 5% monthly mortality
   220→  const baseRate = shortage * 0.055;  // 90% shortage → 5% monthly
   221→  
   222→  return baseRate * rampMultiplier * recoveryMultiplier;
   223→}
