   269→  // 2. Update temperature (recovers as soot clears)
   270→  winter.temperatureAnomaly = calculateTemperatureAnomaly(winter.currentSoot);
   271→  
   272→  // 3. Update crop yields (improve as temperature recovers)
   273→  winter.cropYieldMultiplier = calculateCropYield(winter.temperatureAnomaly);
   274→  
   275→  // 4. Update starvation rate
   276→  winter.monthlyStarvationRate = calculateStarvationRate(
   277→    winter.cropYieldMultiplier,
   278→    winter.monthsSinceWar
   279→  );
   280→  
   281→  // 5. Apply starvation deaths
   282→  if (winter.monthlyStarvationRate > 0) {
   283→    const population = state.humanPopulationSystem.population;
   284→    const starvationDeaths = population * winter.monthlyStarvationRate;
   285→    
   286→    if (starvationDeaths > 0.001) {  // Only log if > 1 million deaths
   287→      addAcuteCrisisDeaths(
   288→        state,
   289→        starvationDeaths,
   290→        'Nuclear winter famine - agricultural collapse (global)',
   291→        1.00,
   292→        'famine',
   293→        RootCause.conflict,  // Root: Nuclear war caused nuclear winter
   294→        'HIGH'
   295→      );
   296→      winter.totalWinterDeaths += starvationDeaths;
   297→      
   298→      // Log significant events
   299→      if (winter.monthsSinceWar % 12 === 0 || winter.monthsSinceWar === 6) {
   300→        console.log(`\n☢️  NUCLEAR WINTER (Month ${state.currentMonth}, ${winter.monthsSinceWar} months since war)`);
   301→        console.log(`   Soot remaining: ${winter.currentSoot.toFixed(1)} Tg (${(winter.currentSoot / winter.sootInStratosphere * 100).toFixed(0)}% of peak)`);
   302→        console.log(`   Temperature: ${winter.temperatureAnomaly.toFixed(1)}°C below baseline`);
   303→        console.log(`   Crop yield: ${(winter.cropYieldMultiplier * 100).toFixed(0)}%`);
   304→        console.log(`   Starvation: ${(starvationDeaths * 1000).toFixed(1)}M deaths this month`);
   305→        console.log(`   Total winter deaths: ${(winter.totalWinterDeaths * 1000).toFixed(0)}M`);
   306→      }
   307→    }
   308→  }
   309→  
   310→  // 6. Update radiation zones
   311→  updateRadiationZones(state, winter);
   312→  
   313→  // 7. Check if nuclear winter is over (soot cleared, starvation negligible)
   314→  if (winter.currentSoot < 0.5 && winter.monthlyStarvationRate < 0.001) {
   315→    winter.active = false;
   316→    console.log(`\n✅ NUCLEAR WINTER ENDED (Month ${state.currentMonth})`);
   317→    console.log(`   Duration: ${winter.monthsSinceWar} months (${(winter.monthsSinceWar / 12).toFixed(1)} years)`);
   318→    console.log(`   Total deaths: ${(winter.totalWinterDeaths * 1000).toFixed(0)}M starvation + ${(winter.totalRadiationDeaths * 1000).toFixed(0)}M radiation`);
   319→    console.log(`   Final temperature: ${(winter.baselineTemperature + winter.temperatureAnomaly).toFixed(1)}°C (baseline: ${winter.baselineTemperature}°C)`);
   320→  }
   321→}
   322→
   323→/**
   324→ * Update radiation zones (decay and mortality)
   325→ */
   326→function updateRadiationZones(state: GameState, winter: NuclearWinterState): void {
   327→  if (winter.radiationZones.length === 0) return;
   328→  
   329→  let totalRadiationDeaths = 0;
   330→  
   331→  winter.radiationZones.forEach(zone => {
   332→    // Decay radiation over time
   333→    zone.currentLevel = zone.currentLevel * (1 - zone.decayRate);
   334→    
   335→    // Apply radiation mortality (scales with radiation level)
   336→    const radiationMortality = zone.monthlyDeathRate * zone.currentLevel;
   337→    
   338→    // Apply to country if we have country tracking
   339→    if (state.countryPopulationSystem) {
   340→      const country = state.countryPopulationSystem.countries[zone.country];
   341→      if (country && country.population > 0.1) {  // Only if country has >100K people
   342→        const countryDeaths = (country.population / 1000) * radiationMortality;  // Convert to billions
   343→        totalRadiationDeaths += countryDeaths;
   344→        
   345→        // Log significant radiation deaths annually
   346→        const monthsSinceHit = state.currentMonth - zone.hitMonth;
   347→        if (monthsSinceHit % 12 === 0 && countryDeaths > 0.001) {
   348→          console.log(`   ☢️  Radiation deaths in ${zone.country}: ${(countryDeaths * 1000).toFixed(1)}M (level: ${(zone.currentLevel * 100).toFixed(0)}%)`);
   349→        }
   350→      }
   351→    }
   352→  });
   353→  
   354→  if (totalRadiationDeaths > 0) {
   355→    addAcuteCrisisDeaths(
   356→      state,
   357→      totalRadiationDeaths,
   358→      'Radiation poisoning (nuclear zones)',
   359→      0.30,
   360→      'war',
   361→      RootCause.conflict,
   362→      'HIGH'
   363→    );
   364→    winter.totalRadiationDeaths += totalRadiationDeaths;
   365→  }
   366→  
   367→  // Remove zones with negligible radiation (<1%)
   368→  winter.radiationZones = winter.radiationZones.filter(z => z.currentLevel > 0.01);
   369→}
